using Agro360.Application.Contracts;
using Agro360.Infrastructure.Persistence;
using Agro360.Multitenancy;
using Agro360.SharedKernel;
using Dapper;

namespace Agro360.Infrastructure.Services;

public sealed class MaterialRequestService(DatabaseExecutor database, ITenantContext tenant) : IMaterialRequestService
{
    public Task<Guid> CreateAsync(CreateMaterialRequestCommand c, CancellationToken ct)
    {
        if (c.Items is null || c.Items.Count == 0) throw new DomainException("Informe ao menos um item válido.", "agro360.material_request_items_required");
        var priority = Guard.Required(c.Priority, nameof(c.Priority), 12).ToUpperInvariant();
        if (priority == "URGENT" && string.IsNullOrWhiteSpace(c.UrgencyReason)) throw new DomainException("Justifique a urgência.", "agro360.material_request_urgency_reason_required");
        return database.InTenantTransactionAsync(async (db, tx) =>
        {
            var farm = await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.geo_farms where tenant_id=@TenantId and id=@FarmId and deleted_at is null)", new { tenant.TenantId, c.FarmId }, tx, cancellationToken:ct));
            if (!farm) throw new DomainException("A unidade não pertence ao contexto ativo.", "agro360.material_request_scope");
            if (c.WarehouseId.HasValue && !await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.inventory_warehouses where tenant_id=@TenantId and id=@WarehouseId and farm_id=@FarmId and deleted_at is null)", new { tenant.TenantId, c.WarehouseId, c.FarmId }, tx, cancellationToken:ct))) throw new DomainException("O depósito não pertence à unidade selecionada.", "agro360.material_request_warehouse_scope");
            var products = (await db.QueryAsync<Product>(new CommandDefinition("select id,base_unit Unit from agro360.inventory_products where tenant_id=@TenantId and id=any(@Ids) and deleted_at is null", new { tenant.TenantId, Ids=c.Items.Select(x=>x.ProductId).Distinct().ToArray() }, tx, cancellationToken:ct))).ToDictionary(x=>x.Id);
            foreach(var item in c.Items) { Guard.Positive(item.Quantity,nameof(item.Quantity)); if(!products.TryGetValue(item.ProductId,out var p)) throw new DomainException("Produto inativo ou fora do cliente.","agro360.material_request_product"); if(!string.Equals(p.Unit,item.Unit,StringComparison.OrdinalIgnoreCase)) throw new DomainException("A unidade do item é incompatível com o produto.","agro360.inventory_unit_mismatch"); }
            var id=Guid.CreateVersion7();
            var requiresApproval=await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.inventory_material_approval_rules r where r.tenant_id=@TenantId and r.active and (r.farm_id is null or r.farm_id=@FarmId) and (r.priority is null or r.priority=@Priority) and (r.category is null or exists(select 1 from agro360.inventory_products p where p.id=any(@Products) and p.category=r.category)))",new {tenant.TenantId,c.FarmId,Priority=priority,Products=c.Items.Select(x=>x.ProductId).ToArray()},tx,cancellationToken:ct));
            var status=c.Submit?(requiresApproval?"AWAITING_APPROVAL":"APPROVED"):"DRAFT";
            await db.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_material_requests(id,tenant_id,farm_id,warehouse_id,cost_center_id,requester_id,purpose,related_type,related_id,needed_on,priority,urgency_reason,notes,status,created_by,updated_by) values(@Id,@TenantId,@FarmId,@WarehouseId,@CostCenterId,@UserId,@Purpose,@RelatedType,@RelatedId,@NeededOn,@Priority,@UrgencyReason,@Notes,@Status,@UserId,@UserId)",new {Id=id,tenant.TenantId,c.FarmId,c.WarehouseId,c.CostCenterId,UserId=tenant.UserId,Purpose=Guard.Required(c.Purpose,nameof(c.Purpose),40).ToUpperInvariant(),c.RelatedType,c.RelatedId,c.NeededOn,Priority=priority,c.UrgencyReason,c.Notes,Status=status},tx,cancellationToken:ct));
            foreach(var x in c.Items) await db.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_material_request_items(id,tenant_id,request_id,product_id,requested,unit) values(@Id,@TenantId,@RequestId,@ProductId,@Quantity,@Unit)",new {Id=Guid.CreateVersion7(),tenant.TenantId,RequestId=id,x.ProductId,x.Quantity,Unit=x.Unit.ToLowerInvariant()},tx,cancellationToken:ct));
            await Event(db,tx,id,c.Submit?"SUBMITTED":"CREATED",status,null,ct); return id;
        },ct);
    }
    public Task<PagedResult<MaterialRequestListDto>> ListAsync(int page,int pageSize,string? search,string? status,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var p=new {tenant.TenantId,Search=string.IsNullOrWhiteSpace(search)?null:search.Trim(),Status=string.IsNullOrWhiteSpace(status)?null:status,Take=pageSize,Skip=(page-1)*pageSize};var total=await db.ExecuteScalarAsync<long>(new CommandDefinition("select count(*) from agro360.inventory_material_requests r where tenant_id=@TenantId and (@Status is null or status=@Status) and (@Search is null or r.number::text ilike '%'||@Search||'%')",p,tx,cancellationToken:ct));var rows=(await db.QueryAsync<MaterialRequestListDto>(new CommandDefinition("select r.id,'REQ-'||lpad(r.number::text,6,'0') Number,coalesce(u.name,u.email) Requester,f.name Farm,r.needed_on NeededOn,r.priority,r.status,case when sum(i.requested)=0 then 0 else round(100*sum(i.delivered)/sum(i.requested),2) end FulfillmentPercent,r.version from agro360.inventory_material_requests r join agro360.geo_farms f on f.tenant_id=r.tenant_id and f.id=r.farm_id left join agro360.identity_users u on u.id=r.requester_id and u.tenant_id=r.tenant_id join agro360.inventory_material_request_items i on i.request_id=r.id and i.tenant_id=r.tenant_id where r.tenant_id=@TenantId and (@Status is null or r.status=@Status) and (@Search is null or r.number::text ilike '%'||@Search||'%') group by r.id,u.name,u.email,f.name order by r.needed_on,r.number limit @Take offset @Skip",p,tx,cancellationToken:ct))).ToArray();return new(rows,page,pageSize,total);},ct);
    public Task<MaterialRequestDetailDto> GetAsync(Guid id,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{
        var h=await db.QuerySingleOrDefaultAsync<Header>(new CommandDefinition("select r.*, 'REQ-'||lpad(r.number::text,6,'0') Number,f.name Farm,coalesce(u.name,u.email) Requester from agro360.inventory_material_requests r join agro360.geo_farms f on f.id=r.farm_id and f.tenant_id=r.tenant_id left join agro360.identity_users u on u.id=r.requester_id and u.tenant_id=r.tenant_id where r.tenant_id=@TenantId and r.id=@Id",new {tenant.TenantId,Id=id},tx,cancellationToken:ct))??throw new NotFoundException("Requisição",id);
        var raw=(await db.QueryAsync<Item>(new CommandDefinition("select i.*,p.name Product from agro360.inventory_material_request_items i join agro360.inventory_products p on p.id=i.product_id and p.tenant_id=i.tenant_id where i.tenant_id=@TenantId and i.request_id=@Id order by p.name",new {tenant.TenantId,Id=id},tx,cancellationToken:ct))).ToArray();var items=new List<MaterialRequestItemDto>();foreach(var i in raw){var av=(await db.QueryAsync<MaterialAvailabilityDto>(new CommandDefinition("select b.warehouse_id WarehouseId,w.name Warehouse,null::varchar LotNumber,null::date ExpiresOn,b.available Physical,0::numeric Blocked,b.reserved,b.available-b.reserved Available from agro360.inventory_stock_balances b join agro360.inventory_warehouses w on w.id=b.warehouse_id and w.tenant_id=b.tenant_id where b.tenant_id=@TenantId and b.product_id=@ProductId order by w.name",new {tenant.TenantId,i.ProductId},tx,cancellationToken:ct))).ToArray();items.Add(new(i.Id,i.ProductId,i.Product,i.Requested,i.Reserved,i.Delivered,i.Consumed,i.Returned,i.Unit,av));}var history=(await db.QueryAsync<MaterialRequestEventDto>(new CommandDefinition("select e.type,e.status,coalesce(u.name,u.email) Actor,e.reason,e.occurred_at OccurredAt from agro360.inventory_material_request_events e left join agro360.identity_users u on u.id=e.actor_id and u.tenant_id=e.tenant_id where e.tenant_id=@TenantId and e.request_id=@Id order by e.occurred_at desc",new {tenant.TenantId,Id=id},tx,cancellationToken:ct))).ToArray();return new(h.Id,h.Number,h.FarmId,h.Farm,h.WarehouseId,h.Requester,h.CostCenterId,h.Purpose,h.RelatedType,h.RelatedId,h.NeededOn,h.Priority,h.Notes,h.Status,h.Version,items,history);},ct);
    public Task DecideAsync(Guid id,MaterialRequestDecisionCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{var decision=c.Decision.ToUpperInvariant();if(decision is not("APPROVE" or "REJECT" or "ADJUST"))throw new DomainException("Decisão inválida.");if(decision!="APPROVE")Guard.Required(c.Reason,nameof(c.Reason),1000);var r=await Lock(db,tx,id,ct);if(r.Status!="AWAITING_APPROVAL"||r.Version!=c.Version)throw new ConflictException("A requisição mudou ou não aguarda aprovação.");if(r.RequesterId==tenant.UserId&&await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.inventory_material_approval_rules where tenant_id=@TenantId and active and segregation_required)",new {tenant.TenantId},tx,cancellationToken:ct)))throw new DomainException("A segregação configurada impede autoaprovação.","agro360.material_request_segregation");var s=decision=="APPROVE"?"APPROVED":decision=="REJECT"?"REJECTED":"ADJUSTMENT_REQUESTED";await Update(db,tx,id,c.Version,s,ct);await Event(db,tx,id,"DECISION",s,c.Reason,ct);},ct);
    public Task ReserveAsync(Guid id,MaterialReservationCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{if(await Exists(db,tx,"inventory_material_reservations",c.IdempotencyKey,ct))return;var r=await Lock(db,tx,id,ct);if(r.Version!=c.Version||r.Status is not("APPROVED" or "RESERVED" or "PARTIALLY_DELIVERED"))throw new ConflictException("Estado ou versão não permite reservar.");var i=await LockItem(db,tx,id,c.ItemId,ct);var q=Guard.Positive(c.Quantity,nameof(c.Quantity));var b=await db.QuerySingleOrDefaultAsync<Balance>(new CommandDefinition("select id,available,reserved,version from agro360.inventory_stock_balances where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=@ProductId for update",new {tenant.TenantId,c.WarehouseId,i.ProductId},tx,cancellationToken:ct))??throw new ConflictException("Saldo não localizado.");if(q>i.Requested-i.Reserved||q>b.Available-b.Reserved)throw new ConflictException("A reserva supera a necessidade ou disponibilidade autorizada.");await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_balances set reserved=reserved+@Q,version=version+1,updated_at=now() where id=@Id",new {Q=q,b.Id},tx,cancellationToken:ct));await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_material_request_items set reserved=reserved+@Q where id=@ItemId; insert into agro360.inventory_material_reservations(tenant_id,request_id,item_id,warehouse_id,quantity,idempotency_key,created_by) values(@TenantId,@RequestId,@ItemId,@WarehouseId,@Q,@Key,@UserId)",new {tenant.TenantId,RequestId=id,c.ItemId,c.WarehouseId,Q=q,Key=c.IdempotencyKey,UserId=tenant.UserId},tx,cancellationToken:ct));await Update(db,tx,id,c.Version,"RESERVED",ct);await Event(db,tx,id,"RESERVED","RESERVED",null,ct);},ct);
    public Task<Guid> DeliverAsync(Guid id,MaterialDeliveryCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{var prior=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("select id from agro360.inventory_material_deliveries where tenant_id=@TenantId and idempotency_key=@Key",new {tenant.TenantId,Key=c.IdempotencyKey},tx,cancellationToken:ct));if(prior.HasValue)return prior.Value;var r=await Lock(db,tx,id,ct);if(r.Version!=c.Version||r.Status is not("RESERVED" or "PARTIALLY_DELIVERED"))throw new ConflictException("Estado ou versão não permite entrega.");var i=await LockItem(db,tx,id,c.ItemId,ct);var q=Guard.Positive(c.Quantity,nameof(c.Quantity));if(!string.Equals(i.Unit,c.Unit,StringComparison.OrdinalIgnoreCase)||q>i.Reserved-i.Delivered||q>i.Requested-i.Delivered)throw new DomainException("Quantidade ou unidade excede a autorização.","agro360.material_delivery_invalid");if(c.Lots is null||c.Lots.Count==0||c.Lots.Sum(x=>x.Quantity)!=q)throw new DomainException("A soma dos lotes deve corresponder à entrega.","agro360.material_delivery_lots");var reservation=await db.QuerySingleOrDefaultAsync<Reservation>(new CommandDefinition("select * from agro360.inventory_material_reservations where tenant_id=@TenantId and request_id=@RequestId and item_id=@ItemId and status='ACTIVE' and quantity-fulfilled-released>=@Q order by created_at for update limit 1",new {tenant.TenantId,RequestId=id,c.ItemId,Q=q},tx,cancellationToken:ct))??throw new ConflictException("Não há reserva elegível para esta entrega.");var b=await db.QuerySingleAsync<Balance>(new CommandDefinition("select id,available,reserved,average_cost AverageCost,version from agro360.inventory_stock_balances where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=@ProductId for update",new {tenant.TenantId,reservation.WarehouseId,i.ProductId},tx,cancellationToken:ct));if(q>b.Reserved||q>b.Available)throw new ConflictException("O saldo reservado mudou; atualize a tela.");foreach(var lot in c.Lots){Guard.Positive(lot.Quantity,nameof(lot.Quantity));var ok=await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.inventory_stock_lots where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=@ProductId and lot_number=@Lot and quantity>=@Q and (expires_on is null or expires_on>=current_date))",new {tenant.TenantId,reservation.WarehouseId,i.ProductId,Lot=lot.LotNumber,Q=lot.Quantity},tx,cancellationToken:ct));if(!ok)throw new ConflictException($"Lote {lot.LotNumber} indisponível, vencido ou incompatível.");}
        var movement=Guid.CreateVersion7();var delivery=Guid.CreateVersion7();await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_balances set available=available-@Q,reserved=reserved-@Q,version=version+1,updated_at=now() where id=@BalanceId; update agro360.inventory_material_request_items set delivered=delivered+@Q where id=@ItemId; update agro360.inventory_material_reservations set fulfilled=fulfilled+@Q,status=case when fulfilled+@Q+released=quantity then 'FULFILLED' else status end where id=@ReservationId; insert into agro360.inventory_stock_movements(id,tenant_id,warehouse_id,product_id,movement_type,quantity,unit,unit_cost,total_cost,reference_type,reference_id,notes,idempotency_key,balance_after,average_cost_after,balance_version,occurred_at,created_by) values(@Movement,@TenantId,@WarehouseId,@ProductId,'CONSUMPTION',@Q,@Unit,@Cost,@Total,'MATERIAL_DELIVERY',@Delivery,'Entrega interna rastreável',@Key,@After,@Cost,@BalanceVersion,now(),@UserId); insert into agro360.inventory_material_deliveries(id,tenant_id,request_id,item_id,warehouse_id,quantity,unit,destination,receiver,direct_consumption,unit_cost,movement_id,idempotency_key,delivered_by) values(@Delivery,@TenantId,@RequestId,@ItemId,@WarehouseId,@Q,@Unit,@Destination,@Receiver,@Direct,@Cost,@Movement,@Key,@UserId)",new {Q=q,BalanceId=b.Id,c.ItemId,ReservationId=reservation.Id,Movement=movement,tenant.TenantId,WarehouseId=reservation.WarehouseId,ProductId=i.ProductId,Unit=i.Unit,Cost=b.AverageCost,Total=q*b.AverageCost,Delivery=delivery,RequestId=id,Key=c.IdempotencyKey,After=b.Available-q,BalanceVersion=b.Version+1,UserId=tenant.UserId,Destination=Guard.Required(c.Destination,nameof(c.Destination),300),Receiver=Guard.Required(c.Receiver,nameof(c.Receiver),160),Direct=c.DirectConsumption},tx,cancellationToken:ct));foreach(var lot in c.Lots){await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_lots set quantity=quantity-@Q where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=@ProductId and lot_number=@Lot; insert into agro360.inventory_material_delivery_lots(tenant_id,delivery_id,lot_number,quantity) values(@TenantId,@Delivery,@Lot,@Q)",new {tenant.TenantId,WarehouseId=reservation.WarehouseId,ProductId=i.ProductId,Lot=lot.LotNumber,Q=lot.Quantity,Delivery=delivery},tx,cancellationToken:ct));}if(c.DirectConsumption){await InsertConsumption(db,tx,id,delivery,q,"DIRECT_DELIVERY",id,null,c.IdempotencyKey+":consumption",b.AverageCost,ct);await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_material_request_items set consumed=consumed+@Q where id=@ItemId",new {Q=q,c.ItemId},tx,cancellationToken:ct));}var complete=await db.ExecuteScalarAsync<bool>(new CommandDefinition("select bool_and(delivered=requested) from agro360.inventory_material_request_items where tenant_id=@TenantId and request_id=@Id",new {tenant.TenantId,Id=id},tx,cancellationToken:ct));var status=complete?"DELIVERED":"PARTIALLY_DELIVERED";await Update(db,tx,id,c.Version,status,ct);await Event(db,tx,id,"DELIVERED",status,null,ct);return delivery;},ct);
    public Task<Guid> ConsumeAsync(Guid id,MaterialConsumptionCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{var prior=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("select id from agro360.inventory_material_consumptions where tenant_id=@TenantId and idempotency_key=@Key",new {tenant.TenantId,Key=c.IdempotencyKey},tx,cancellationToken:ct));if(prior.HasValue)return prior.Value;var d=await db.QuerySingleOrDefaultAsync<Delivery>(new CommandDefinition("select * from agro360.inventory_material_deliveries where tenant_id=@TenantId and request_id=@RequestId and id=@Id and status='DELIVERED' for update",new {tenant.TenantId,RequestId=id,Id=c.DeliveryId},tx,cancellationToken:ct))??throw new NotFoundException("Entrega",c.DeliveryId);if(d.DirectConsumption)throw new ConflictException("Esta entrega já reconheceu consumo direto; uma segunda baixa é proibida.");var used=await db.ExecuteScalarAsync<decimal>(new CommandDefinition("select coalesce(sum(quantity),0) from agro360.inventory_material_consumptions where tenant_id=@TenantId and delivery_id=@Id",new {tenant.TenantId,Id=c.DeliveryId},tx,cancellationToken:ct));var returned=await db.ExecuteScalarAsync<decimal>(new CommandDefinition("select coalesce(sum(quantity),0) from agro360.inventory_material_returns where tenant_id=@TenantId and delivery_id=@Id",new {tenant.TenantId,Id=c.DeliveryId},tx,cancellationToken:ct));var q=Guard.Positive(c.Quantity,nameof(c.Quantity));if(q>d.Quantity-used-returned)throw new ConflictException("O consumo supera o saldo elegível da entrega.");var result=await InsertConsumption(db,tx,id,d.Id,q,Guard.Required(c.DestinationType,nameof(c.DestinationType),30),c.DestinationId,c.CostCenterId,c.IdempotencyKey,d.UnitCost,ct);await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_material_request_items set consumed=consumed+@Q where id=@ItemId",new {Q=q,d.ItemId},tx,cancellationToken:ct));await Event(db,tx,id,"CONSUMED","DELIVERED",null,ct);return result;},ct);
    public Task<Guid> ReturnAsync(Guid id,MaterialReturnCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{var prior=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("select id from agro360.inventory_material_returns where tenant_id=@TenantId and idempotency_key=@Key",new {tenant.TenantId,Key=c.IdempotencyKey},tx,cancellationToken:ct));if(prior.HasValue)return prior.Value;var d=await db.QuerySingleOrDefaultAsync<Delivery>(new CommandDefinition("select * from agro360.inventory_material_deliveries where tenant_id=@TenantId and request_id=@RequestId and id=@Id and status='DELIVERED' for update",new {tenant.TenantId,RequestId=id,Id=c.DeliveryId},tx,cancellationToken:ct))??throw new NotFoundException("Entrega",c.DeliveryId);var used=await db.ExecuteScalarAsync<decimal>(new CommandDefinition("select coalesce(sum(quantity),0) from agro360.inventory_material_consumptions where tenant_id=@TenantId and delivery_id=@Id",new {tenant.TenantId,Id=c.DeliveryId},tx,cancellationToken:ct));var returned=await db.ExecuteScalarAsync<decimal>(new CommandDefinition("select coalesce(sum(quantity),0) from agro360.inventory_material_returns where tenant_id=@TenantId and delivery_id=@Id",new {tenant.TenantId,Id=c.DeliveryId},tx,cancellationToken:ct));var q=Guard.Positive(c.Quantity,nameof(c.Quantity));if(q>d.Quantity-used-returned)throw new ConflictException("A devolução supera a sobra elegível da entrega.");var condition=c.Condition.ToUpperInvariant();if(condition is not("GOOD" or "DAMAGED" or "UNKNOWN"))throw new DomainException("Condição inválida.");Guid? movement=null;if(condition=="GOOD"){var b=await db.QuerySingleOrDefaultAsync<Balance>(new CommandDefinition("select id,available,reserved,average_cost AverageCost,version from agro360.inventory_stock_balances where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=(select product_id from agro360.inventory_material_request_items where id=@ItemId) for update",new {tenant.TenantId,c.WarehouseId,d.ItemId},tx,cancellationToken:ct))??throw new ConflictException("Depósito de devolução sem saldo cadastrado.");movement=Guid.CreateVersion7();await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_balances set available=available+@Q,version=version+1,updated_at=now() where id=@BalanceId; insert into agro360.inventory_stock_movements(id,tenant_id,warehouse_id,product_id,movement_type,quantity,unit,unit_cost,total_cost,lot_number,reference_type,reference_id,notes,idempotency_key,balance_after,average_cost_after,balance_version,occurred_at,created_by) select @Movement,@TenantId,@WarehouseId,i.product_id,'RECEIPT',@Q,i.unit,@Cost,@Total,@Lot,'MATERIAL_RETURN',@Delivery,@Reason,@Key,@After,@Cost,@Version,now(),@UserId from agro360.inventory_material_request_items i where i.id=@ItemId",new {Movement=movement,tenant.TenantId,c.WarehouseId,Q=q,Cost=d.UnitCost,Total=q*d.UnitCost,Lot=c.LotNumber,Delivery=d.Id,c.Reason,Key=c.IdempotencyKey,After=b.Available+q,Version=b.Version+1,UserId=tenant.UserId,d.ItemId,BalanceId=b.Id},tx,cancellationToken:ct));}var rid=Guid.CreateVersion7();await db.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_material_returns(id,tenant_id,request_id,delivery_id,warehouse_id,quantity,lot_number,condition,reason,responsible,movement_id,status,idempotency_key,returned_by) values(@Id,@TenantId,@RequestId,@Delivery,@WarehouseId,@Q,@Lot,@Condition,@Reason,@Responsible,@Movement,@Status,@Key,@UserId); update agro360.inventory_material_request_items set returned=returned+@Q where id=@ItemId",new {Id=rid,tenant.TenantId,RequestId=id,Delivery=d.Id,c.WarehouseId,Q=q,Lot=Guard.Required(c.LotNumber,nameof(c.LotNumber),100),Condition=condition,Reason=Guard.Required(c.Reason,nameof(c.Reason),1000),Responsible=Guard.Required(c.Responsible,nameof(c.Responsible),160),Movement=movement,Status=condition=="GOOD"?"AVAILABLE":"AWAITING_INSPECTION",Key=c.IdempotencyKey,UserId=tenant.UserId,d.ItemId},tx,cancellationToken:ct));await Event(db,tx,id,"RETURNED","DELIVERED",c.Reason,ct);return rid;},ct);
    public Task CancelAsync(Guid id,MaterialRequestActionCommand c,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{Guard.Required(c.Reason,nameof(c.Reason),1000);var r=await Lock(db,tx,id,ct);if(r.Version!=c.Version||r.Status is "DELIVERED" or "PARTIALLY_DELIVERED" or "CLOSED")throw new ConflictException("Entregas existentes exigem devolução ou estorno controlado.");var reservations=(await db.QueryAsync<Reservation>(new CommandDefinition("select * from agro360.inventory_material_reservations where tenant_id=@TenantId and request_id=@Id and status='ACTIVE' for update",new {tenant.TenantId,Id=id},tx,cancellationToken:ct))).ToArray();foreach(var x in reservations){var left=x.Quantity-x.Fulfilled-x.Released;await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_balances b set reserved=reserved-@Q,version=version+1,updated_at=now() from agro360.inventory_material_request_items i where i.id=@ItemId and b.tenant_id=@TenantId and b.warehouse_id=@WarehouseId and b.product_id=i.product_id; update agro360.inventory_material_reservations set released=released+@Q,status='RELEASED' where id=@Id",new {Q=left,x.ItemId,tenant.TenantId,x.WarehouseId,x.Id},tx,cancellationToken:ct));}await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_material_requests set status='CANCELLED',cancelled_at=now(),cancelled_by=@UserId,cancellation_reason=@Reason,version=version+1,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and version=@Version",new {tenant.TenantId,Id=id,Version=c.Version,UserId=tenant.UserId,c.Reason},tx,cancellationToken:ct));await Event(db,tx,id,"CANCELLED","CANCELLED",c.Reason,ct);},ct);
    public Task<IReadOnlyCollection<InventoryLookupDto>> LookupsAsync(string type,CancellationToken ct)=>database.InTenantTransactionAsync(async(db,tx)=>{var sql=type switch{"products"=>"select id,name Label,base_unit Unit from agro360.inventory_products where tenant_id=@TenantId and deleted_at is null order by name","warehouses"=>"select id,name Label,null::varchar Unit from agro360.inventory_warehouses where tenant_id=@TenantId and deleted_at is null order by name","farms"=>"select id,name Label,null::varchar Unit from agro360.geo_farms where tenant_id=@TenantId and deleted_at is null order by name","cost-centers"=>"select id,name Label,null::varchar Unit from agro360.finance_cost_centers where tenant_id=@TenantId and deleted_at is null and active order by name","people"=>"select id,name Label,null::varchar Unit from agro360.identity_users where tenant_id=@TenantId and deleted_at is null and status='ACTIVE' order by name",_=>throw new DomainException("Consulta auxiliar inválida.")};return (IReadOnlyCollection<InventoryLookupDto>)(await db.QueryAsync<InventoryLookupDto>(new CommandDefinition(sql,new {tenant.TenantId},tx,cancellationToken:ct))).ToArray();},ct);
    private async Task<Guid> InsertConsumption(System.Data.IDbConnection db,System.Data.IDbTransaction tx,Guid request,Guid delivery,decimal q,string type,Guid destination,Guid? cost,string key,decimal unitCost,CancellationToken ct){var id=Guid.CreateVersion7();await db.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_material_consumptions(id,tenant_id,request_id,delivery_id,quantity,destination_type,destination_id,cost_center_id,total_cost,idempotency_key,consumed_by) values(@Id,@TenantId,@Request,@Delivery,@Q,@Type,@Destination,@Cost,@Total,@Key,@UserId)",new {Id=id,tenant.TenantId,Request=request,Delivery=delivery,Q=q,Type=type,Destination=destination,Cost=cost,Total=q*unitCost,Key=key,UserId=tenant.UserId},tx,cancellationToken:ct));return id;}
    private Task<bool> Exists(System.Data.IDbConnection db,System.Data.IDbTransaction tx,string table,string key,CancellationToken ct)=>db.ExecuteScalarAsync<bool>(new CommandDefinition($"select exists(select 1 from agro360.{table} where tenant_id=@TenantId and idempotency_key=@Key)",new {tenant.TenantId,Key=key},tx,cancellationToken:ct));
    private async Task<Request> Lock(System.Data.IDbConnection db,System.Data.IDbTransaction tx,Guid id,CancellationToken ct)=>await db.QuerySingleOrDefaultAsync<Request>(new CommandDefinition("select id,status,version,requester_id RequesterId from agro360.inventory_material_requests where tenant_id=@TenantId and id=@Id for update",new {tenant.TenantId,Id=id},tx,cancellationToken:ct))??throw new NotFoundException("Requisição",id);
    private async Task<Item> LockItem(System.Data.IDbConnection db,System.Data.IDbTransaction tx,Guid request,Guid item,CancellationToken ct)=>await db.QuerySingleOrDefaultAsync<Item>(new CommandDefinition("select i.*,p.name Product from agro360.inventory_material_request_items i join agro360.inventory_products p on p.id=i.product_id and p.tenant_id=i.tenant_id where i.tenant_id=@TenantId and i.request_id=@Request and i.id=@Item for update",new {tenant.TenantId,Request=request,Item=item},tx,cancellationToken:ct))??throw new NotFoundException("Item",item);
    private async Task Update(System.Data.IDbConnection db,System.Data.IDbTransaction tx,Guid id,long version,string status,CancellationToken ct){if(await db.ExecuteAsync(new CommandDefinition("update agro360.inventory_material_requests set status=@Status,version=version+1,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and version=@Version",new {tenant.TenantId,Id=id,Version=version,Status=status,UserId=tenant.UserId},tx,cancellationToken:ct))!=1)throw new ConflictException("A requisição foi atualizada por outra sessão.");}
    private Task Event(System.Data.IDbConnection db,System.Data.IDbTransaction tx,Guid request,string type,string status,string? reason,CancellationToken ct)=>db.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_material_request_events(tenant_id,request_id,type,status,reason,actor_id) values(@TenantId,@Request,@Type,@Status,@Reason,@UserId)",new {tenant.TenantId,Request=request,Type=type,Status=status,Reason=reason,UserId=tenant.UserId},tx,cancellationToken:ct));
    private sealed class Product{public Guid Id{get;init;}public string Unit{get;init;}="";}
    private sealed class Request{public Guid Id{get;init;}public string Status{get;init;}="";public long Version{get;init;}public Guid RequesterId{get;init;}}
    private sealed class Header{public Guid Id{get;init;}public string Number{get;init;}="";public Guid FarmId{get;init;}public string Farm{get;init;}="";public Guid? WarehouseId{get;init;}public string Requester{get;init;}="";public Guid? CostCenterId{get;init;}public string Purpose{get;init;}="";public string? RelatedType{get;init;}public Guid? RelatedId{get;init;}public DateOnly NeededOn{get;init;}public string Priority{get;init;}="";public string? Notes{get;init;}public string Status{get;init;}="";public long Version{get;init;}}
    private sealed class Item{public Guid Id{get;init;}public Guid ProductId{get;init;}public string Product{get;init;}="";public decimal Requested{get;init;}public decimal Reserved{get;init;}public decimal Delivered{get;init;}public decimal Consumed{get;init;}public decimal Returned{get;init;}public string Unit{get;init;}="";}
    private sealed class Balance{public Guid Id{get;init;}public decimal Available{get;init;}public decimal Reserved{get;init;}public decimal AverageCost{get;init;}public long Version{get;init;}}
    private sealed class Reservation{public Guid Id{get;init;}public Guid ItemId{get;init;}public Guid WarehouseId{get;init;}public decimal Quantity{get;init;}public decimal Fulfilled{get;init;}public decimal Released{get;init;}}
    private sealed class Delivery{public Guid Id{get;init;}public Guid ItemId{get;init;}public decimal Quantity{get;init;}public decimal UnitCost{get;init;}public bool DirectConsumption{get;init;}}
